#include <stdio.h>

typedef struct { float coeff; int exp; } Term;

int addPolynomials(Term p1[], int n1, Term p2[], int n2, Term res[]) {
    int i = 0, j = 0, k = 0;
    while (i < n1 && j < n2) {
        if (p1[i].exp == p2[j].exp) {
            res[k].coeff = p1[i].coeff + p2[j].coeff;
            res[k++].exp = p1[i++].exp;
            j++;
        } else if (p1[i].exp > p2[j].exp) res[k++] = p1[i++];
        else res[k++] = p2[j++];
    }
    while (i < n1) res[k++] = p1[i++];
    while (j < n2) res[k++] = p2[j++];
    return k;
}

int main() {
    Term p1[] = {{5, 2}, {3, 1}, {2, 0}};
    Term p2[] = {{4, 2}, {1, 0}};
    Term res[10];
    int total = addPolynomials(p1, 3, p2, 2, res);
    for (int i = 0; i < total; i++) printf("%.0fx^%d ", res[i].coeff, res[i].exp);
    printf("\n");
    return 0;
}

#include <stdio.h>

typedef struct { int row, col, val; } Term;

void createTriplet(int mat[4][5], int r, int c, Term trip[]) {
    int k = 1;
    trip[0].row = r; trip[0].col = c;
    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) {
            if (mat[i][j] != 0) {
                trip[k].row = i; trip[k].col = j; trip[k].val = mat[i][j];
                k++;
            }
        }
    }
    trip[0].val = k - 1;
}

int main() {
    int mat[4][5] = {{0,0,3,0,4}, {0,0,0,0,0}, {0,2,0,0,0}, {0,0,0,5,0}};
    Term trip[10];
    createTriplet(mat, 4, 5, trip);
    for (int i = 0; i <= trip[0].val; i++) printf("%d %d %d\n", trip[i].row, trip[i].col, trip[i].val);
    return 0;
}

#include <stdio.h>

typedef struct { int row, col, val; } Term;

void fastTranspose(Term a[], Term b[]) {
    int num_cols = a[0].col, num_terms = a[0].val;
    b[0].row = num_cols; b[0].col = a[0].row; b[0].val = num_terms;
    if (num_terms <= 0) return;

    int row_terms[100] = {0}, starting_pos[100] = {0};
    for (int i = 1; i <= num_terms; i++) row_terms[a[i].col]++;
    starting_pos[0] = 1;
    for (int i = 1; i < num_cols; i++) starting_pos[i] = starting_pos[i - 1] + row_terms[i - 1];
    for (int i = 1; i <= num_terms; i++) {
        int j = starting_pos[a[i].col]++;
        b[j].row = a[i].col; b[j].col = a[i].row; b[j].val = a[i].val;
    }
}

int main() {
    Term a[5] = {{3, 3, 3}, {0, 0, 10}, {0, 2, 20}, {2, 1, 30}};
    Term b[5];
    fastTranspose(a, b);
    for (int i = 0; i <= b[0].val; i++) printf("%d %d %d\n", b[i].row, b[i].col, b[i].val);
    return 0;
}

#include <stdio.h>
#define MAX 5

int stack[MAX];
int top = -1;

void push(int x) {
    if (top == MAX - 1) {
        printf("Stack Overflow! Cannot push %d\n", x);
        return;
    }
    stack[++top] = x;
    printf("Pushed: %d\n", x);
}

int pop() {
    if (top == -1) {
        printf("Stack Underflow!\n");
        return -1;
    }
    return stack[top--];
}

int main() {
    push(10); push(20); push(30);
    printf("Popped: %d\n", pop());
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *arr;
    int top;
    int capacity;
} DynamicStack;

DynamicStack* createStack(int cap) {
    DynamicStack *s = (DynamicStack*)malloc(sizeof(DynamicStack));
    s->capacity = cap;
    s->top = -1;
    s->arr = (int*)malloc(s->capacity * sizeof(int));
    return s;
}

void push(DynamicStack *s, int val) {
    if (s->top == s->capacity - 1) {
        s->capacity *= 2;
        s->arr = (int*)realloc(s->arr, s->capacity * sizeof(int));
        printf("[Capacity doubled to %d]\n", s->capacity);
    }
    s->arr[++(s->top)] = val;
}

int main() {
    DynamicStack *s = createStack(2);
    push(s, 1); push(s, 2); push(s, 3); // Triggers resize
    return 0;
}

