#include <stdio.h>
#define MAX 5

int cq[MAX];
int front = 0, rear = 0;

void enqueue(int val) {
    if ((rear + 1) % MAX == front) {
        printf("Circular Queue Overflow!\n");
        return;
    }
    rear = (rear + 1) % MAX;
    cq[rear] = val;
    printf("Enqueued: %d at %d\n", val, rear);
}

int dequeue() {
    if (front == rear) {
        printf("Circular Queue Underflow!\n");
        return -1;
    }
    front = (front + 1) % MAX;
    return cq[front];
}

int main() {
    enqueue(10); enqueue(20); enqueue(30); enqueue(40);
    printf("Dequeued: %d\n", dequeue());
    enqueue(50); // Wraps around to index 0!
    return 0;
}

#include <stdio.h>
#define MAX 6

int arr[MAX];
int top1 = -1, top2 = MAX;

void push1(int x) {
    if (top1 + 1 == top2) { printf("Stack Overflow!\n"); return; }
    arr[++top1] = x;
}

void push2(int x) {
    if (top1 + 1 == top2) { printf("Stack Overflow!\n"); return; }
    arr[--top2] = x;
}

int pop1() { return (top1 == -1) ? -1 : arr[top1--]; }
int pop2() { return (top2 == MAX) ? -1 : arr[top2++]; }

int main() {
    push1(10); push1(20);
    push2(90); push2(80);
    printf("Pop1: %d, Pop2: %d\n", pop1(), pop2());
    return 0;
}

vtu-ise-s3-1bcs305-2025-m3-t3.technicalConcept:
A Singly Linked List (SLL) or Chain is a dynamic collection of self-referential structures (nodes) allocated independently in heap memory.
• Node Representation in C:
```c
struct Node {
    int data;
    struct Node *next;
};
```
• Head Pointer: Points to the first node; `NULL` indicates an empty list.
• Primary Operations:
  - Insert at beginning: Allocate node, `newNode->next = head`, `head = newNode` (Time: $O(1)$).
  - Insert at end: Traverse to tail node where `curr->next == NULL`, set `curr->next = newNode` (Time: $O(N)$).
  - Delete node: Link predecessor directly to successor (`prev->next = curr->next`), then `free(curr)` (Time: $O(N)$).

