#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *arr;
    int top;
    int capacity;
} DynamicStack;

DynamicStack* createStack(int cap) {
    DynamicStack *s = (DynamicStack*)malloc(sizeof(DynamicStack));
    s->capacity = cap;
    s->top = -1;
    s->arr = (int*)malloc(s->capacity * sizeof(int));
    return s;
}

void push(DynamicStack *s, int val) {
    if (s->top == s->capacity - 1) {
        s->capacity *= 2;
        s->arr = (int*)realloc(s->arr, s->capacity * sizeof(int));
        printf("[Capacity doubled to %d]\n", s->capacity);
    }
    s->arr[++(s->top)] = val;
}

int main() {
    DynamicStack *s = createStack(2);
    push(s, 1); push(s, 2); push(s, 3); // Triggers resize
    return 0;
}

