#include <stdio.h>
#define MAX 5

int cq[MAX];
int front = 0, rear = 0;

void enqueue(int val) {
    if ((rear + 1) % MAX == front) {
        printf("Circular Queue Overflow!\n");
        return;
    }
    rear = (rear + 1) % MAX;
    cq[rear] = val;
    printf("Enqueued: %d at %d\n", val, rear);
}

int dequeue() {
    if (front == rear) {
        printf("Circular Queue Underflow!\n");
        return -1;
    }
    front = (front + 1) % MAX;
    return cq[front];
}

int main() {
    enqueue(10); enqueue(20); enqueue(30); enqueue(40);
    printf("Dequeued: %d\n", dequeue());
    enqueue(50); // Wraps around to index 0!
    return 0;
}

