#include <stdio.h>
#define MAX 6

int arr[MAX];
int top1 = -1, top2 = MAX;

void push1(int x) {
    if (top1 + 1 == top2) { printf("Stack Overflow!\n"); return; }
    arr[++top1] = x;
}

void push2(int x) {
    if (top1 + 1 == top2) { printf("Stack Overflow!\n"); return; }
    arr[--top2] = x;
}

int pop1() { return (top1 == -1) ? -1 : arr[top1--]; }
int pop2() { return (top2 == MAX) ? -1 : arr[top2++]; }

int main() {
    push1(10); push1(20);
    push2(90); push2(80);
    printf("Pop1: %d, Pop2: %d\n", pop1(), pop2());
    return 0;
}

