1BCS305_M3_T6.technicalConcept:
A Doubly Linked List (DLL) consists of nodes with bidirectional links:
```c
struct DNode {
    int data;
    struct DNode *prev;
    struct DNode *next;
};
```
• Advantages: Can be traversed forward and backward; a node can delete itself in $O(1)$ time without searching for its predecessor (`node->prev->next = node->next`).
• Disadvantages: Requires extra pointer storage (two addresses per node) and overhead to maintain two link pointers during insertion and deletion.
• Boundary Checks: Always check if `node->prev != NULL` (not head) and `node->next != NULL` (not tail) before dereferencing.

codeSnippets.code:
#include <stdio.h>
#include <stdlib.h>

struct DNode {
    int data;
    struct DNode *prev, *next;
};

struct DNode* insertFront(struct DNode *head, int val) {
    struct DNode *n = (struct DNode*)malloc(sizeof(struct DNode));
    n->data = val; n->prev = NULL; n->next = head;
    if (head != NULL) head->prev = n;
    return n;
}

struct DNode* deleteNode(struct DNode *head, struct DNode *del) {
    if (!head || !del) return head;
    if (head == del) head = del->next;
    if (del->next != NULL) del->next->prev = del->prev;
    if (del->prev != NULL) del->prev->next = del->next;
    free(del);
    return head;
}

int main() {
    struct DNode *head = NULL;
    head = insertFront(head, 20);
    head = insertFront(head, 10);
    return 0;
}

