struct LNode* merge(struct LNode *h1, struct LNode *h2) {
    if (!h1) return h2;
    if (!h2) return h1;
    if (h1->key > h2->key) { struct LNode *t = h1; h1 = h2; h2 = t; } // Min-heap
    h1->right = merge(h1->right, h2);
    if (!h1->left || (h1->right && h1->left->dist < h1->right->dist)) {
        struct LNode *t = h1->left; h1->left = h1->right; h1->right = t;
    }
    h1->dist = (h1->right ? h1->right->dist + 1 : 1);
    return h1;
}

