void fastTranspose(Term a[], Term b[]) {
    int num_cols = a[0].col, num_terms = a[0].val;
    b[0].row = num_cols; b[0].col = a[0].row; b[0].val = num_terms;
    if (num_terms <= 0) return;

    int row_terms[100] = {0}, starting_pos[100] = {0};
    for (int i = 1; i <= num_terms; i++) row_terms[a[i].col]++;
    starting_pos[0] = 1;
    for (int i = 1; i < num_cols; i++) starting_pos[i] = starting_pos[i - 1] + row_terms[i - 1];
    for (int i = 1; i <= num_terms; i++) {
        int j = starting_pos[a[i].col]++;
        b[j].row = a[i].col; b[j].col = a[i].row; b[j].val = a[i].val;
    }
}

