void push(int x) { stack[++top] = x; }
int pop() { return stack[top--]; }

int evaluatePostfix(char *exp) {
    for (int i = 0; exp[i]; i++) {
        char c = exp[i];
        if (isdigit(c)) push(c - '0');
        else {
            int op2 = pop();
            int op1 = pop();
            switch (c) {
                case '+': push(op1 + op2); break;
                case '-': push(op1 - op2); break;
                case '*': push(op1 * op2); break;
                case '/': push(op1 / op2); break;
                case '^': push((int)pow(op1, op2)); break;
            }
        }
    }
    return pop();
}

int main() {
    char exp[] = "623+-382/+*"; // 6 + 2 - 3 ...
    printf("Result: %d\n", evaluatePostfix("53+82-*4/")); // (5+3)*(8-2)/4 = 12
    return 0;
}

