#include <stdio.h>
#define MAX 5

int queue[MAX];
int front = 0, rear = -1;

void enqueue(int val) {
    if (rear == MAX - 1) {
        printf("Queue Overflow!\n");
        return;
    }
    queue[++rear] = val;
    printf("Enqueued: %d\n", val);
}

int dequeue() {
    if (front > rear) {
        printf("Queue Underflow!\n");
        return -1;
    }
    return queue[front++];
}

int main() {
    enqueue(10); enqueue(20); enqueue(30);
    printf("Dequeued: %d\n", dequeue()); // 10
    return 0;
}

