#include <stdio.h>
#include <stdlib.h>

struct Node { int key; struct Node *left, *right; };

struct Node* minValueNode(struct Node* node) {
    struct Node* curr = node;
    while (curr && curr->left != NULL) curr = curr->left;
    return curr;
}

struct Node* deleteNode(struct Node* root, int key) {
    if (root == NULL) return root;
    if (key < root->key) root->left = deleteNode(root->left, key);
    else if (key > root->key) root->right = deleteNode(root->right, key);
    else {
        if (root->left == NULL) { struct Node* t = root->right; free(root); return t; }
        else if (root->right == NULL) { struct Node* t = root->left; free(root); return t; }
        struct Node* temp = minValueNode(root->right);
        root->key = temp->key;
        root->right = deleteNode(root->right, temp->key);
    }
    return root;
}

