#include <stdio.h>

int heap[100]; int size = 0;

void insert(int val) {
    int i = size++;
    while (i > 0 && val > heap[(i - 1) / 2]) {
        heap[i] = heap[(i - 1) / 2];
        i = (i - 1) / 2;
    }
    heap[i] = val;
}

int deleteMax() {
    if (size == 0) return -1;
    int maxVal = heap[0];
    int last = heap[--size];
    int i = 0, child;
    while ((child = 2 * i + 1) < size) {
        if (child + 1 < size && heap[child + 1] > heap[child]) child++;
        if (last >= heap[child]) break;
        heap[i] = heap[child];
        i = child;
    }
    heap[i] = last;
    return maxVal;
}

int main() {
    insert(20); insert(50); insert(15);
    printf("Max Priority: %d\n", deleteMax()); // 50
    return 0;
}

